-- Core tenant schema. Rollback: restore before migration; do not drop operational data.
create schema if not exists extensions;
create extension if not exists btree_gist with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create schema app_private;
revoke all on schema app_private from public,anon;
grant usage on schema app_private to authenticated;
set search_path = public,extensions;
create table public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 full_name text not null default '' check(length(full_name)<=120),
 active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.organizations (
 id uuid primary key default gen_random_uuid(),
 name text not null check(length(name) between 1 and 120),
 slug text not null unique check(slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
 timezone text not null default 'Etc/UTC', currency text not null default 'USD' check(currency ~ '^[A-Z]{3}$'),
 logo_url text check(logo_url is null or (length(logo_url)<=1000 and logo_url ~ '^https://')),
 brand_color text not null default '#6fe2ff' check(brand_color ~ '^#[0-9a-fA-F]{6}$'),
 active boolean not null default true, created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),created_by uuid references public.profiles(id)
);
create table public.organization_settings (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), unique(organization_id), booking_enabled boolean not null default false, booking_horizon_days integer not null default 60 check(booking_horizon_days between 1 and 365), booking_lead_minutes integer not null default 60 check(booking_lead_minutes between 0 and 10080), slot_step_minutes integer not null default 10 check(slot_step_minutes between 5 and 60), default_return_days integer check(default_return_days between 1 and 730), retention_due_soon_days integer not null default 7 check(retention_due_soon_days between 0 and 60), retention_lapsed_days integer not null default 90 check(retention_lapsed_days between 1 and 730), barber_can_edit_availability boolean not null default false);
create table public.branches (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), name text not null check(length(name) between 1 and 120), slug text not null check(slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'), address text check(length(address)<=500), phone text check(length(phone)<=30), timezone text not null, active boolean not null default true, unique(organization_id,slug));
create table public.branch_settings (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, unique(organization_id,branch_id), booking_enabled boolean not null default false, foreign key (organization_id,branch_id) references public.branches(organization_id,id));
create table public.branch_business_hours (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, weekday integer not null check(weekday between 0 and 6), opens_at time not null, closes_at time not null, check(closes_at>opens_at), foreign key (organization_id,branch_id) references public.branches(organization_id,id), unique(organization_id,branch_id,weekday,opens_at));
create table public.branch_closures (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, starts_at timestamptz not null, ends_at timestamptz not null, kind text not null default 'closed' check(kind in ('closed','open')), reason text check(length(reason)<=300), check(ends_at>starts_at), foreign key (organization_id,branch_id) references public.branches(organization_id,id));
create table public.organization_memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), profile_id uuid not null references public.profiles(id), role text not null check(role in ('organization_owner','manager','receptionist','barber','finance')), all_branches boolean not null default false, active boolean not null default true, unique(organization_id,profile_id), check(role <> 'organization_owner' or all_branches));
create table public.membership_branch_access (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), membership_id uuid not null, branch_id uuid not null, foreign key(organization_id,membership_id) references public.organization_memberships(organization_id,id), foreign key (organization_id,branch_id) references public.branches(organization_id,id), unique(organization_id,membership_id,branch_id));
create table public.staff (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), name text not null check(length(name) between 1 and 120), slug text not null check(slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'), profile_id uuid references public.profiles(id), active boolean not null default true, color text not null default '#6fe2ff' check(color ~ '^#[0-9a-fA-F]{6}$'), unique(organization_id,slug), unique(organization_id,profile_id));
create table public.staff_branch_assignments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, staff_id uuid not null, active boolean not null default true, foreign key (organization_id,branch_id) references public.branches(organization_id,id), foreign key (organization_id,staff_id) references public.staff(organization_id,id), unique(organization_id,branch_id,staff_id));
create table public.services (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), name text not null check(length(name) between 1 and 120), slug text not null check(slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'), description text check(length(description)<=1000), default_duration_minutes integer not null check(default_duration_minutes between 1 and 480), active boolean not null default true, category text check(length(category)<=80), color text not null default '#d8d3ff' check(color ~ '^#[0-9a-fA-F]{6}$'), composition_mode text not null default 'standalone' check(composition_mode in ('standalone','additive','included','override')), base_service_id uuid, suggested_return_days integer check(suggested_return_days between 1 and 730), foreign key(organization_id,base_service_id) references public.services(organization_id,id), unique(organization_id,slug), check(base_service_id is distinct from id), check(composition_mode not in ('included','override') or base_service_id is not null));
create table public.branch_services (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, service_id uuid not null, active boolean not null default true, duration_minutes integer check(duration_minutes between 1 and 480), price_minor bigint check(price_minor>=0), foreign key (organization_id,branch_id) references public.branches(organization_id,id), foreign key (organization_id,service_id) references public.services(organization_id,id), unique(organization_id,branch_id,service_id));
create table public.staff_service_capabilities (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), staff_id uuid not null, service_id uuid not null, foreign key (organization_id,staff_id) references public.staff(organization_id,id), foreign key (organization_id,service_id) references public.services(organization_id,id), unique(organization_id,staff_id,service_id));
create table public.staff_availability_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, staff_id uuid not null, weekday integer not null check(weekday between 0 and 6), starts_at time not null, ends_at time not null, valid_from date, valid_until date, check(ends_at>starts_at), check(valid_until is null or valid_from is null or valid_until>=valid_from), foreign key(organization_id,branch_id,staff_id) references public.staff_branch_assignments(organization_id,branch_id,staff_id));
