create table public.appointments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid not null, customer_id uuid not null, staff_id uuid not null, starts_at timestamptz not null, ends_at timestamptz not null, status text not null default 'scheduled' check(status in ('scheduled','confirmed','checked_in','in_service','completed','no_show','cancelled','rescheduled')), source text not null default 'internal' check(source in ('internal','public','walk_in','rebooking')), duration_minutes integer not null check(duration_minutes between 1 and 480), price_minor bigint check(price_minor>=0), currency text not null check(currency ~ '^[A-Z]{3}$'), public_reference uuid not null default gen_random_uuid() unique, notes text check(length(notes)<=1000), rebooked_from_id uuid, checked_in_at timestamptz, started_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, cancellation_reason text check(length(cancellation_reason)<=300), during tstzrange generated always as (tstzrange(starts_at,ends_at,'[)')) stored, foreign key (organization_id,branch_id) references public.branches(organization_id,id), foreign key (organization_id,customer_id) references public.customers(organization_id,id), foreign key(organization_id,branch_id,staff_id) references public.staff_branch_assignments(organization_id,branch_id,staff_id), foreign key(organization_id,rebooked_from_id) references public.appointments(organization_id,id), check(ends_at>starts_at), check(ends_at=starts_at+make_interval(mins=>duration_minutes)), exclude using gist (staff_id with =, during with &&) where (status in ('scheduled','confirmed','checked_in','in_service')));
