create table public.notifications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique (organization_id,id), branch_id uuid, profile_id uuid not null references public.profiles(id), title text not null check(length(title)<=160), body text check(length(body)<=500), read_at timestamptz, event_id uuid references public.domain_events(id), foreign key (organization_id,branch_id) references public.branches(organization_id,id), unique(event_id,profile_id));
