create table app_private.gateway_credentials(name text primary key check(name in ('booking','worker')), secret_hash text not null check(length(secret_hash)=64), active boolean not null default true);
create table app_private.idempotency_keys(organization_id uuid not null references public.organizations(id), actor_scope text not null, operation text not null, key uuid not null, fingerprint text not null, response jsonb, created_at timestamptz not null default now(), primary key(organization_id,actor_scope,operation,key));
