revoke all on all tables in schema app_private from public,anon,authenticated;
create index customers_return_idx on public.customers(organization_id,expected_return_at) where archived_at is null and not do_not_contact;
create index customers_name_search_idx on public.customers using gin(name extensions.gin_trgm_ops);
create index appointments_branch_range_idx on public.appointments(organization_id,branch_id,starts_at,id);
create index appointments_staff_range_idx on public.appointments(organization_id,staff_id,starts_at,id);
create index appointments_customer_range_idx on public.appointments(organization_id,customer_id,starts_at desc,id);
