create index events_timeline_idx on public.domain_events(organization_id,branch_id,created_at,id);
-- Index FK prefixes, without adding a second index for an already covered prefix.
do $$
declare r record; cols text; ix_name text;
begin
 for r in select c.conrelid,c.conname,c.conkey from pg_constraint c join pg_namespace n on n.oid=(select relnamespace from pg_class where oid=c.conrelid) where c.contype='f' and n.nspname='public'
 loop
  if not exists(select 1 from pg_index i where i.indrelid=r.conrelid and i.indisvalid and array(select unnest(i.indkey::smallint[]) limit cardinality(r.conkey))=r.conkey) then
   select string_agg(quote_ident(a.attname),',' order by k.ord) into cols from unnest(r.conkey) with ordinality k(num,ord) join pg_attribute a on a.attrelid=r.conrelid and a.attnum=k.num;
   ix_name:=left(r.conname,50)||'_idx';
   execute format('create index %I on %s (%s)',ix_name,r.conrelid::regclass,cols);
  end if;
 end loop;
end $$;
create function app_private.touch_and_protect_tenant() returns trigger language plpgsql set search_path='' as $$
begin
 if tg_op='UPDATE' then
  if to_jsonb(old)->'organization_id' is distinct from to_jsonb(new)->'organization_id' then raise exception 'tenant_immutable' using errcode='23514'; end if;
  if new.id <> old.id then raise exception 'identity_immutable' using errcode='23514'; end if;
 end if;
 if to_jsonb(new) ? 'timezone' and not exists(select 1 from pg_catalog.pg_timezone_names where name=to_jsonb(new)->>'timezone') then raise exception 'invalid_timezone' using errcode='23514'; end if;
 new.updated_at:=now(); return new;
end $$;
create function app_private.deny_history_mutation() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'append_only' using errcode='42501'; end $$;
create function app_private.create_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),120)); return new; end $$;
create trigger auth_create_profile after insert on auth.users for each row execute function app_private.create_profile();
do $$ declare t text; begin
 for t in select tablename from pg_catalog.pg_tables where schemaname='public' loop
  execute format('alter table public.%I enable row level security',t);
  execute format('create trigger protect_record before insert or update on public.%I for each row execute function app_private.touch_and_protect_tenant()',t);
 end loop;
 foreach t in array array['audit_logs','domain_events','appointment_status_history'] loop
  execute format('create trigger append_only before update or delete on public.%I for each row execute function app_private.deny_history_mutation()',t);
 end loop;
end $$;
revoke all on all tables in schema public from public,anon,authenticated;
grant select on all tables in schema public to authenticated;
revoke all on all functions in schema app_private from public,anon,authenticated;
reset search_path;
